-- 种子数据
-- 内功模块：不被PUA
INSERT OR IGNORE INTO lessons (id, module, lesson_index, title, content_json) VALUES (1, '不被PUA', 1, '受害者叙事 vs 策略选择者叙事', '{"one_liner":"同样一件事，用不同的框架讲述，结果完全不同","concept":{"victim":"受害者叙事：事情发生在我身上，我是被动的、无奈的。讲出来的故事里，你是被命运安排的人。","strategist":"策略选择者叙事：我在每个节点做了当时我能做的最优选择。即使结果不完美，选择权始终在我手里。","key_insight":"两者讲的是完全同一段经历——区别只在于你怎么组织这些事实。"},"case":{"source":"菲森科技面试 · 2026年7月","question":"你的整个履历当中普遍工作时长很短，你对这个事情怎么评价？","interviewer":"藤真（菲森科技COO）","your_answer":"只能说接受吧…并不是我主动要去选择离开的…","what_he_heard":["只能接受 → 这个人觉得自己是受害者","并不是我主动要离开的 → 他没有职业选择的标准","沉默 → 他没有反思过这个问题"],"what_he_wanted":["每段经历都是我的主动选择 → 我是一个有标准的人","我来菲森也是基于同样的选择逻辑 → 这次选择是深思熟虑的","具体的归因 → 我在持续成长"],"deep_insight":"藤真问这个问题的真实目的不是让你解释为什么短——他是在测试你如何看待自己的过去。"},"exercise":{"question":"用「策略选择者」视角，重新描述你的短任期经历。","hint":"不用回避事实。同样的经历，换一个框架来组织。","placeholder":"我的第一份工作在易加油，当时我选择加入的原因是____，在那里我学会了____。当我意识到____之后，我主动选择离开，因为我想补____的能力…"},"next_preview":"识别你的受害者叙事触发模式"}');

-- ═══════════════════════════════════════════
-- 跨境课程模块：L1 看价格
-- ═══════════════════════════════════════════

-- 课1：亚马逊价格入门
INSERT OR IGNORE INTO lessons (id, module, lesson_index, title, content_json) VALUES (10, '跨境·看价格', 1, '亚马逊上的价格到底怎么看', '{"one_liner":"划线价、成交价、优惠券——三个价格常常不一样，看懂它们才能在分析时不掉坑","concept":{"point1":"划线价 vs 成交价","point1_detail":"划线价（List Price/MSRP）是厂商建议零售价，只是一个参照物。真正的成交价（Price）才是消费者付的钱。很多产品划线价 $299，实际成交价 $199，如果你按 $299 去算利润，从第一步就错了。","point2":"优惠券和促销","point2_detail":"亚马逊的优惠券（Coupon）在页面上勾选后额外减价。有些产品标价 $249，页面有 $50 Coupon，实际到手 $199。另外 Prime Day、黑五、季末清仓时价格波动极大——今天 $199 明天就可能回到 $299。","point3":"变体价格差异","point3_detail":"同一个产品不同容量、不同颜色、含不含太阳能板——价格可能差一倍。拆解前先确认你分析的是哪个具体变体，以及为什么这个变体卖得最好。","key_insight":"拆品的第一个动作：打开链接，找到当前实际成交价（不是划线价），确认有没有优惠券，确认你选的是主流变体。"},"case":{"source":"真实案例 · 亚马逊便携储能品类","scenario":"你在亚马逊搜 Portable Power Station，看到一个产品标题写着 $399 但现在 $239。点进去发现是 300Wh 版本，同一个 listing 下 500Wh 版本 $359。两个变体差了 $120。","analysis":"$239 vs $359，差了整整 50%。你需要判断：为什么 500Wh 比 300Wh 贵这么多？是电池多了 200Wh 的成本差异，还是品牌定价策略？去 1688 搜同类 300Wh 和 500Wh 的出厂价，你就知道品牌在这个品上的加价空间有多大。","deep_insight":"同一个 listing 下不同变体的价格差，暴露了品牌真实的定价逻辑——你的竞争对手每一度电敢加多少价。"},"exercise":{"question":"打开这个产品链接（ASIN: B0CLG6FYLQ），填写以下信息：1）当前实际售价（不是划线价）2）有没有优惠券？减多少？3）有哪些变体？哪个变体看起来卖得最好？","hint":"实际价格在页面上以大字显示的那个数字，优惠券在价格旁边有个小勾选框。变体在标题下方可以切换（不同容量/颜色/套装）。","placeholder":"实际售价：$____\n优惠券：有/无，金额$____\n变体列表：\n- 变体1（容量/规格）：$____\n- 变体2（容量/规格）：$____\n卖得最好的是____，因为____"},"next_preview":"课2：储能品类怎么分高中低端"}');

-- 课2：价位段认知
INSERT OR IGNORE INTO lessons (id, module, lesson_index, title, content_json) VALUES (11, '跨境·看价格', 2, '储能品类怎么分高中低端', '{"one_liner":"预算型 <$200、中端 $200-500、高端 >$500——每个价位段用户买的东西完全不同","concept":{"point1":"三个价位段","point1_detail":"预算型（<$200）：容量 200-300Wh，大多用普通锂电而非 LFP，品牌杂、差评多、退货率高。中端（$200-500）：容量 300-1000Wh，LFP 电池是标配，品牌开始有认知度，这是中小卖家最容易切入的区间。高端（>$500）：容量 1000Wh+，品牌溢价明显，用户买的不只是电——是品牌信任、售后保障、可扩展生态。","point2":"价位段的门槛配置","point2_detail":"预算型的门槛：100W+ USB-C PD、至少 2 个 AC 口、重量 <5kg。中端的门槛：500W+ AC 输出、LFP 电池、快充 <2h、至少 3 个 AC 口。高端门槛：1000W+ 输出、UPS 功能、可扩展电池、App 控制。","point3":"品牌怎么覆盖价位段","point3_detail":"EcoFlow 的 River 系列打预算和中端，Delta 系列打中端和高端。同一个品牌用不同产品线覆盖不同人群——但核心技术（快充、LFP、逆变器）是共享的。你作为新进入者，应该先盯一个价位段打透，而不是同时做三个。","key_insight":"价位段不是按容量分的，是按用户愿意花多少钱分的。同一个 500Wh，露营党可能觉得 $300 是上限，家庭应急党可能觉得 $500 也值。"},"case":{"source":"对比分析 · 三个价位段的典型产品","scenario":"GRECELL 300W（$100，预算型）vs Jackery 300 Plus（$239，中端入门）vs EcoFlow Delta 2（$399，中端主力）。三个都是储能电源，但用户画像完全不同。","analysis":"GRECELL 买家：第一次买储能电源，看价格最低就下单了。Jackery 买家：知道这个品牌，愿意多花 $139 买个安心。EcoFlow 买家：做了功课，对比过参数，选快充最快的那款。三种人花的是三种钱，买的是三种东西——GRECELL 买的是'电量'，Jackery 买的是'放心'，EcoFlow 买的是'效率'。","deep_insight":"同一个品类，不同价位段对应不同用户，不同用户买的是不同的价值主张。你不是在跟所有品牌竞争——你只在跟你同一个价位段的产品竞争。"},"exercise":{"question":"我发给你 3 个不同价位的储能产品链接，你分别判断：1）属于哪个价位段？2）这个价位段的用户最可能在什么场景下使用？3）跟同价位竞品比，它贵了还是便宜了？","hint":"不要只看容量。看品牌、电池类型（LFP vs 锂电）、接口数、保修年限。这些才是价位段的真正分界线。","placeholder":"品1：价位段____｜用户场景____｜vs竞品____\n品2：价位段____｜用户场景____｜vs竞品____\n品3：价位段____｜用户场景____｜vs竞品____"},"next_preview":"课3：一个储能电源的成本拆开看"}');

-- 课3：成本拆解
INSERT OR IGNORE INTO lessons (id, module, lesson_index, title, content_json) VALUES (12, '跨境·看价格', 3, '一个储能电源的成本拆开看', '{"one_liner":"电芯 40-50%、逆变器 15-20%、BMS 10%、外壳 10%、组装 5-10%——知道钱花在哪，你才能跟工厂谈价","concept":{"point1":"成本结构全景","point1_detail":"以一台 300Wh 便携储能为例：电芯（18650 或 21700 锂电池）占 40-50%，约 ¥150-200；逆变器（DC转AC）占 15-20%，约 ¥60-80；BMS 电池管理系统占 10%，约 ¥40；外壳+配件+包装占 10%，约 ¥40；人工组装+测试占 5-10%，约 ¥30。BOM 总成本约 ¥320-390。如果 1688 上报价 ¥280，大概率电芯是旧货或者 BMS 缩水了。","point2":"电芯是最大的变量","point2_detail":"同样 300Wh，用 A 品 21700 电芯 vs B 品 18650 电芯，成本差 30-50%。用 LFP（磷酸铁锂）vs NMC（三元锂），成本差 15-20%。LFP 贵但寿命长（3000 次 vs 500 次），品牌产品几乎全用 LFP。预算型产品用普通锂电——这解释了为什么 GRECELL $100 能做而 Jackery $239 才够。","point3":"美规 110V vs 国标 220V","point3_detail":"同一个工厂的同一个产品，美规版和国行版的 BOM 成本差异不到 5%（主要是逆变器规格不同和插头模具）。但美规版的市场售价可能是国行版的 1.5-2 倍——这个差价不是成本决定的，是市场定价权决定的。","key_insight":"成本结构是你跟工厂谈判的底气。知道电芯大概多少钱、逆变器大概多少钱，工厂报出来的价你就能判断合不合理——报价太低可能在电芯上省了，报价太高可能把你当外行宰。"},"case":{"source":"拆解 · 一个 300Wh 储能电源的 BOM","scenario":"你在 1688 找到一家深圳工厂，他们报了一台美规 110V 300Wh LFP 便携储能，MOQ 100台，单价 ¥380。你要判断这个价格能不能做。","analysis":"按成本结构拆：LFP 电芯（200Wh 实际可用，配 300Wh 标称）≈¥160；300W 纯正弦波逆变器≈¥70；16 串 LFP BMS≈¥45；阻燃 ABS 外壳+彩盒≈¥35；组装+老化测试≈¥25。合计 BOM≈¥335。工厂报 ¥380，毛利 ¥45/台（约 12%）。如果再加英文说明书+美规插头认证（UL），单台成本再加 ¥20。¥400/台的出厂价是合理的。","deep_insight":"工厂的成本结构跟你猜的可能完全不一样。所以你不需要精确知道每颗螺丝多少钱——你只需要知道电芯占大头、逆变器第二、其他加起来不到 30%。有了这个坐标系，工厂报价你就心里有数了。"},"exercise":{"question":"我给你一个 500Wh 储能电源的完整规格表。请估算：1）电芯大概什么规格？成本多少？2）整机 BOM 大概多少？3）如果 1688 上报价 ¥550，你觉得算合理还算偏高？","hint":"500Wh LFP 电芯按 ¥0.8-1.0/Wh 估算。逆变器 500W 约 ¥100-150。BMS 约 ¥50-80。壳子 ¥50。组装 ¥30。加起来就是 BOM 粗估。","placeholder":"电芯估算：规格____｜成本约 ¥____\n逆变器：____W｜成本约 ¥____\nBMS：成本约 ¥____\n外壳+配件：¥____\n组装：¥____\nBOM 合计：¥____\n1688 报价 ¥550 判断：____"},"next_preview":"课4：1688怎么搜才能找到靠谱价格"}');

-- 课4：1688找货入门
INSERT OR IGNORE INTO lessons (id, module, lesson_index, title, content_json) VALUES (13, '跨境·看价格', 4, '1688怎么搜才能找到靠谱价格', '{"one_liner":"搜品类不搜品牌、搜出口不搜内销、搜工厂不搜经销商——1688三个找货法则","concept":{"point1":"搜品类不搜品牌","point1_detail":"在 1688 上搜\"Jackery 300W 同款\"→ 大概率没结果或假货。搜\"美规 便携储能 OEM 300W\"→ 能找到真正做美规出口的工厂。品牌货是给消费者看的品名，工厂货有工厂自己的叫法——搜核心参数（容量+功率+电压），不要搜品牌名。","point2":"加对关键词","point2_detail":"找美规产品加：美规、110V、出口、OEM、ODM。找供应商加：工厂、源头、厂家直销。过滤二道贩子加：支持验厂、可定制、现货批发。几个组合示例：『便携储能 美规 OEM』『300W 户外电源 出口 110V』『磷酸铁锂 储能 源头工厂』。","point3":"三秒辨工厂还是经销商","point3_detail":"看店铺名：XX电子厂/XX能源科技 → 工厂。XX贸易/XX电子商行 → 经销商。看产品线：只做储能+户外电源 → 专业工厂。什么品类都有（储能、充电宝、音箱、风扇）→ 一定不是工厂。看详情页：有产线实拍图、车间照片、检测设备 → 工厂。全是白底精修渲染图 → 二道贩子。","key_insight":"1688 上 70% 的店铺不是工厂。花 30 秒看店铺首页，能筛掉大部分无效选项。"},"case":{"source":"实操演示 · 从亚马逊产品到 1688 供应商","scenario":"你在亚马逊看到一款 Portable Power Station 300W, 288Wh，售价 $199。你要在 1688 上找同类产品的出厂价——不是找这个品牌的同款，而是找'有能力做类似产品'的工厂。","analysis":"搜『便携储能 300W 美规 OEM』→ 找到 3 家工厂。A 厂：深圳宝安，专注储能 5 年，300W LFP 报价 ¥380/台 MOQ 100。B 厂：东莞，什么都做，300W 报价 ¥290/台 MOQ 50。C 厂：惠州，只做出口，300W 报价 ¥420/台 MOQ 500。A 厂最靠谱——产品线集中、有产线照片、报价合理。B 厂太便宜可能是旧电芯或 BMS 缩水。C 厂专业但量太大不适合新手。","deep_insight":"你不需要找到亚马逊品牌的同款——你需要找到能做出'和那个东西差不多的产品'的工厂。品牌货有定制模具和专属 BMS，你在 1688 上不可能找到一模一样的。但你找的工厂告诉你的报价，让你知道'如果我来做，成本底线在哪'。"},"exercise":{"question":"我给你一个亚马逊储能产品的 ASIN。你去 1688 搜同品类（不是同品牌），找到至少 2 家供应商，记录：1）工厂名和所在地 2）最低报价和 MOQ 3）你判断是真工厂还是二道贩子？理由是什么？","hint":"搜『产品类型+核心参数+美规/出口/ODM』。看店铺首页有没有产线照片。看产品线集中不集中。如果可以，发一条消息『老板好，这款能做美规吗？MOQ 多少？』看对方怎么回。","placeholder":"工厂1：名称____｜地点____｜报价 ¥____｜MOQ____｜判断____\n工厂2：名称____｜地点____｜报价 ¥____｜MOQ____｜判断____\n我的收获（一句话）：____"},"next_preview":"课5：3分钟利润速算——拿到价格后快速判断能不能做"}');

-- 课5：利润速算
INSERT OR IGNORE INTO lessons (id, module, lesson_index, title, content_json) VALUES (14, '跨境·看价格', 5, '3分钟利润速算：能不能做？', '{"one_liner":"售价×0.7-采购成本$-头程$-FBA$——剩>20%值得做，<10%直接放弃","concept":{"point1":"成本公式模板","point1_detail":"采购成本$ = 1688出厂价÷7.2（汇率）。头程=重量kg×$2.5（含锂电池）。FBA配送费=亚马逊计算器查（$8-15不等）。佣金=售价×15%（能源品类）。广告=售价×15%（新品估算）。总成本=以上五项的加总。利润=售价-总成本。毛利率=利润÷售价×100%。","point2":"三个判断阈值","point2_detail":">30%：利润空间健康，毫不犹豫继续看。<10%：算不过账，直接放弃。20-30%：可行但紧——广告费不能超预算，退货率需要控制在 3% 以内，供应链成本不能涨。10-20%：只有大规模（日销 20+单）才可能赚钱，小卖家不建议碰。","point3":"常见算错场景","point3_detail":"场景1：用了划线价而不是成交价——高估了售价。场景2：忘了头程是危险品渠道——低估了运费（含锂电 $2.5/kg 不是 $1.4）。场景3：广告费按 10% 估——新品期实际 20-30%。场景4：没算退货损耗（3-5%）。这些误差每个单独看不大，加起来会把一个看似 30% 利润的产品拉到 10%。","key_insight":"利润速算不是财务分析——它是一个快速过滤器。3 分钟内算出大约有没有戏：有戏就深挖，没戏就换下一个。不需要精确到小数点后两位。"},"case":{"source":"实战算例 · 一个真实的储能电源","scenario":"亚马逊上一台 768Wh LFP 便携储能，实际成交价 $359。1688 工厂报价 ¥850/台 MOQ 100。产品重量约 10kg。你需要在 3 分钟内判断：这个品值不值得做。","analysis":"采购成本$ = 850÷7.2 = $118。头程 = 10kg×$2.5 = $25。FBA（计算器查）= $13。佣金 = $359×0.15 = $53.85。广告 = $359×0.15 = $53.85。总成本 = 118+25+13+53.85+53.85 = $263.70。利润 = 359-263.70 = $95.30。毛利率 = 95.30÷359×100 = 26.5%。判断：毛利率 26.5%，在 20-30% 区间——可行但紧。如果广告费能控制到 12%（ACOS 优化后），毛利率可提到 31%。值得测。","deep_insight":"26.5% 和 31% 的差别就是广告费从 15% 压到 12%——这 3 个百分点的差距，靠的不是算账，是运营能力。但你在阶段 0 不需要考虑这个——你只需要判断有没有利润空间。"},"exercise":{"question":"我给你一个亚马逊储能产品 + 1688 参考报价。3 分钟内完成全套利润估算：采购成本$、头程$、FBA$、佣金$、广告$、总成本、利润、毛利率、最终判断（值得测/观望/放弃）。","hint":"用模板：￥÷7.2 → kg×2.5 → 查计算器 → 售价×0.15 → 售价×0.15。加总。减法。除法。判断。","placeholder":"采购成本$：¥____÷7.2 = $____\n头程$：____kg×$2.5 = $____\nFBA$：查计算器 = $____\n佣金$：$____×0.15 = $____\n广告$：$____×0.15 = $____\n总成本$：____\n利润$：____\n毛利率：____%\n判断：____"},"next_preview":"L1 结业测试：5个陌生品，独立完成全套判断"}');
